/**
 * Top-bar "pipelines" stat chip that doubles as the pipeline filter: click it to pick
 * which pipelines are loaded. No pipeline ticked means all of them (the API default).
 *
 * Pipelines with execution modes (pipelines.yaml `execution_modes`) get mode chips: tick
 * several to stack them on the canvas, the starred one is in front (server-side, so every
 * view - detail, search, lineage - follows the front mode). A mode without
 * artifacts is generated by the backend first (needs `project_dir`). With a `project_dir`,
 * every mode chip has its own button that reruns `dbt docs generate` for that mode (shown
 * or not); a pipeline without modes gets that button next to its name. The runs themselves
 * show up in the task indicator.
 */

import { AlertTriangle, Check, ChevronDown, Loader2, RefreshCw, Star } from 'lucide-react'
import { useEffect, useRef, useState } from 'react'

import { mockGraph } from '../api/mock'
import type { GenerationJob, PipelineInfo, PipelineModeInfo } from '../api/types'
import { isActive, latestJob, useExplorerStore } from '../store/useExplorerStore'

function modeTitle(mode: PipelineModeInfo, job: GenerationJob | undefined): string {
  const vars = Object.entries(mode.vars)
    .map(([key, value]) => `${key}: ${JSON.stringify(value)}`)
    .join(', ')
  const lines = [`${mode.name}${vars ? ` - ${vars}` : ''}`]
  lines.push(mode.available ? `generated ${mode.generated_at ?? 'at unknown time'}` : `no artifacts: ${mode.manifest}`)
  if (job && isActive(job)) lines.push('dbt docs generate is running')
  else if (job?.status === 'failed') lines.push(`last dbt run failed: ${job.error ?? 'see tasks'}`)
  return lines.join('\n')
}

function modeLabel(mode: PipelineModeInfo, job: GenerationJob | undefined, canGenerate: boolean): string {
  if (job && isActive(job)) return `${mode.name} · generating…`
  if (mode.available) return mode.name
  if (job?.status === 'failed') return `${mode.name} · failed`
  return canGenerate ? `${mode.name} · not generated` : `${mode.name} · not available`
}

/**
 * Execution modes of one pipeline as chips (multi-select): a ticked mode is shown, the
 * starred one is in front, the other ticked modes are stacked behind it on the canvas.
 * Unticked modes are not shown. At least one mode stays ticked.
 */
function ModeChips({ info }: { info: PipelineInfo }) {
  const setPipelineModes = useExplorerStore((s) => s.setPipelineModes)
  const regenerate = useExplorerStore((s) => s.regenerate)
  const switching = useExplorerStore((s) => s.modeSwitching)
  const jobs = useExplorerStore((s) => s.jobs)
  const canGenerate = Boolean(info.can_generate)
  // what is really in front; a mode being generated joins (or moves to the front) once done
  const front = info.active_mode ?? info.modes[0]?.name
  const selected = [front, ...(info.stacked_modes ?? [])].filter((m): m is string => Boolean(m))
  const busy = switching !== null

  const toggle = (mode: string) => {
    if (!selected.includes(mode)) return void setPipelineModes(info.name, [...selected, mode], front!)
    const rest = selected.filter((m) => m !== mode)
    if (rest.length === 0) return // one mode is always shown
    void setPipelineModes(info.name, rest, mode === front ? rest[0] : front!)
  }
  const bringToFront = (mode: string) => {
    if (mode === front) return
    void setPipelineModes(info.name, selected.includes(mode) ? selected : [...selected, mode], mode)
  }

  return (
    <div className="mode-chips" role="group" aria-label={`Execution modes of ${info.name}`}>
      {info.modes.map((mode) => {
        const job = latestJob(jobs, info.name, mode.name)
        const on = selected.includes(mode.name)
        const isFront = mode.name === front
        const usable = mode.available || canGenerate
        const generating = (job !== undefined && isActive(job)) || info.pending_mode === mode.name
        return (
          <span
            key={mode.name}
            className="mode-chip"
            data-on={on}
            data-front={isFront}
            title={modeTitle(mode, job)}
          >
            <button
              type="button"
              className="mode-chip__toggle"
              disabled={busy || !usable}
              aria-pressed={on}
              onClick={() => toggle(mode.name)}
              aria-label={`${on ? 'Hide' : 'Show'} mode ${mode.name}`}
            >
              {generating ? (
                <Loader2 size={10} className="spin" aria-label={`generating ${mode.name}`} />
              ) : on ? (
                <Check size={10} strokeWidth={3} />
              ) : null}
              {modeLabel(mode, job, canGenerate)}
            </button>
            {job?.status === 'failed' && !generating && (
              <span
                className="mode-chip__failed"
                aria-label={`last dbt run of ${mode.name} failed`}
                title={`last dbt run failed: ${job.error ?? ''}`}
              >
                <AlertTriangle size={10} />
              </span>
            )}
            {canGenerate && (
              <button
                type="button"
                className="mode-chip__regen"
                disabled={generating}
                onClick={() => void regenerate(info.name, mode.name)}
                title={
                  generating
                    ? `dbt docs generate is running for ${mode.name}`
                    : `${mode.available ? 'Regenerate' : 'Generate'} ${mode.name} with dbt docs generate`
                }
                aria-label={`${mode.available ? 'Regenerate' : 'Generate'} ${info.name} (${mode.name})`}
              >
                <RefreshCw size={10} className={generating ? 'spin' : undefined} />
              </button>
            )}
            <button
              type="button"
              className="mode-chip__front"
              disabled={busy || !usable || isFront}
              onClick={() => bringToFront(mode.name)}
              title={isFront ? `${mode.name} is in front` : `Bring ${mode.name} to the front`}
              aria-label={isFront ? `${mode.name} is in front` : `Bring ${mode.name} to the front`}
            >
              <Star size={10} fill={isFront ? 'currentColor' : 'none'} />
            </button>
          </span>
        )
      })}
      {switching === info.name && <Loader2 size={12} className="spin mode-chips__busy" aria-label="switching modes" />}
    </div>
  )
}

/** Rerun `dbt docs generate` for a pipeline without execution modes (modes have their own, in the chips). */
function RegenerateButton({ info }: { info: PipelineInfo }) {
  const regenerate = useExplorerStore((s) => s.regenerate)
  const job = useExplorerStore((s) => latestJob(s.jobs, info.name, info.active_mode))
  const running = job !== undefined && isActive(job)
  const what = info.active_mode ? `${info.name} (${info.active_mode})` : info.name

  return (
    <>
      {job?.status === 'failed' && (
        <span
          className="pipeline-picker__status pipeline-picker__failed"
          aria-label="last dbt run failed"
          title={`last dbt run failed: ${job.error ?? ''}`}
        >
          <AlertTriangle size={12} />
        </span>
      )}
      <button
        type="button"
        className="pipeline-picker__regen"
        disabled={running}
        onClick={() => void regenerate(info.name, info.active_mode)}
        title={running ? `dbt docs generate is running for ${what}` : `Regenerate ${what} with dbt docs generate`}
        aria-label={`Regenerate ${what}`}
      >
        <RefreshCw size={12} className={running ? 'spin' : undefined} />
      </button>
    </>
  )
}

export function PipelinePicker() {
  const meta = useExplorerStore((s) => s.meta)
  const usingMock = useExplorerStore((s) => s.usingMock)
  const visibleCount = useExplorerStore((s) => s.graph?.stats.pipelines.length ?? 0)
  const selected = useExplorerStore((s) => s.filters.pipelines)
  const setFilters = useExplorerStore((s) => s.setFilters)
  const pipelineInfo = useExplorerStore((s) => s.pipelineInfo)
  const modeError = useExplorerStore((s) => s.modeError)

  const [open, setOpen] = useState(false)
  const rootRef = useRef<HTMLDivElement>(null)

  // the graph only carries the pipelines in view, so take the full list from /meta - plus
  // configured pipelines whose shown mode has no artifacts (else its dropdown is unreachable)
  const loaded = meta?.pipelines ?? (usingMock ? mockGraph.stats.pipelines : [])
  const all = [...new Set([...loaded, ...pipelineInfo.map((p) => p.name)])].sort()
  const infoOf = new Map(pipelineInfo.map((p) => [p.name, p]))
  const filtered = selected.length > 0

  useEffect(() => {
    if (!open) return
    const onPointer = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false)
    }
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpen(false)
    }
    document.addEventListener('pointerdown', onPointer)
    document.addEventListener('keydown', onKey)
    return () => {
      document.removeEventListener('pointerdown', onPointer)
      document.removeEventListener('keydown', onKey)
    }
  }, [open])

  const apply = (next: string[]) => {
    // ticking every pipeline is the same as no filter; keep the URL clean
    void setFilters({ pipelines: next.length === all.length ? [] : next })
  }

  const isOn = (pipeline: string) => !filtered || selected.includes(pipeline)

  const toggle = (pipeline: string) => {
    const current = filtered ? selected : all
    const next = current.includes(pipeline) ? current.filter((p) => p !== pipeline) : [...current, pipeline]
    if (next.length === 0) return // never filter down to nothing
    apply(all.filter((p) => next.includes(p)))
  }

  return (
    <div className="pipeline-picker" ref={rootRef}>
      <button
        type="button"
        className={`stat-chip stat-chip--button ${filtered ? 'stat-chip--filtered' : ''} ${open ? 'stat-chip--open' : ''}`}
        onClick={() => setOpen((v) => !v)}
        aria-haspopup="true"
        aria-expanded={open}
        title="Choose which pipelines are shown"
      >
        <span className="stat-chip__value">
          {filtered && all.length > 0 ? `${visibleCount}/${all.length}` : visibleCount}
        </span>
        <span className="stat-chip__label">
          pipelines <ChevronDown size={10} className="stat-chip__caret" />
        </span>
      </button>

      {open && (
        <div className="pipeline-picker__menu" role="menu">
          <div className="pipeline-picker__head">
            <span>Show pipelines</span>
            <button type="button" className="pipeline-picker__link" onClick={() => apply([])} disabled={!filtered}>
              All
            </button>
          </div>
          {all.length === 0 && <div className="pipeline-picker__empty">No pipelines</div>}
          {modeError && <div className="pipeline-picker__error">{modeError}</div>}
          {all.map((pipeline) => (
            <div key={pipeline} className="pipeline-picker__row">
              <button
                type="button"
                role="menuitemcheckbox"
                aria-checked={isOn(pipeline)}
                className="pipeline-picker__item"
                onClick={() => toggle(pipeline)}
              >
                <span className={`pipeline-picker__box ${isOn(pipeline) ? 'pipeline-picker__box--on' : ''}`}>
                  {isOn(pipeline) && <Check size={11} strokeWidth={3} />}
                </span>
                {pipeline}
              </button>
              {infoOf.get(pipeline)?.can_generate && !infoOf.get(pipeline)?.modes.length && (
                <RegenerateButton info={infoOf.get(pipeline)!} />
              )}
              <button
                type="button"
                className="pipeline-picker__link pipeline-picker__only"
                onClick={() => apply([pipeline])}
                title={`Show only ${pipeline}`}
              >
                only
              </button>
              {infoOf.get(pipeline)?.modes.length ? <ModeChips info={infoOf.get(pipeline)!} /> : null}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}
